import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { io, type Socket } from 'socket.io-client';
import { AudioPresets, Room, RoomEvent, Track, VideoPreset, type RemoteTrack, type LocalTrack } from 'livekit-client';
import { Hash, MonitorUp, Plus, LogOut, Send, Users, Copy, Radio, Wifi, ShieldCheck, Eye, EyeOff, KeyRound, Mic, MicOff, Volume2, VolumeX, Pin, PinOff, Gauge, Settings, X, Save, RotateCw, Pencil, Trash2, ChevronUp, ChevronDown, UserCog, UserRound, Sparkles, Gamepad2, Code2, Rocket, Crown, Palette, Music2, Coffee, Cat, Star, ImagePlus, ImageOff, type LucideIcon } from 'lucide-react';
import './styles.css';

type User = { id:string; email:string; username:string; display_name:string; avatar_icon:string; avatar_color:string; avatar_image:string|null; created_at:string; last_seen:string };
type Channel = { id:string; community_id:string; name:string; type:'text'|'screen'; position:number };
type Community = { id:string; name:string; owner_id:string; icon:string; icon_color:string; icon_image:string|null; invite_code:string; role:'owner'|'admin'|'member'; channels:Channel[] };
type Message = { id:string; channel_id:string; author_id:string; username:string; display_name:string; avatar_icon:string; avatar_color:string; avatar_image:string|null; content:string; created_at:string; edited_at?:string|null };
type Member = { id:string; username:string; display_name:string; avatar_icon:string; avatar_color:string; avatar_image:string|null; last_seen:string; role:string; online?:boolean };
type IconOption = { id:string; label:string; Icon:LucideIcon };
type AudioShareMode = 'window'|'system'|'none';
type CaptureInfo = { surface:'browser'|'window'|'monitor'|'unknown'; hasAudio:boolean; mode:AudioShareMode };
type StreamQuality = 'economy'|'balanced'|'game';
type QualityProfile = { label:string; description:string; width:number; height:number; fps:number; maxBitrate:number; contentHint:'detail'|'motion'; degradationPreference:RTCDegradationPreference; layers:VideoPreset[] };
const QUALITY_PROFILES:Record<StreamQuality,QualityProfile>={
  economy:{label:'Economia',description:'720p · 30 fps · até 2,5 Mbps',width:1280,height:720,fps:30,maxBitrate:2_500_000,contentHint:'detail',degradationPreference:'balanced',layers:[new VideoPreset({width:640,height:360,maxBitrate:750_000,maxFramerate:20}),new VideoPreset({width:320,height:180,maxBitrate:280_000,maxFramerate:15})]},
  balanced:{label:'Equilibrado',description:'1080p · 30 fps · até 5,5 Mbps',width:1920,height:1080,fps:30,maxBitrate:5_500_000,contentHint:'detail',degradationPreference:'maintain-resolution',layers:[new VideoPreset({width:1280,height:720,maxBitrate:2_500_000,maxFramerate:30}),new VideoPreset({width:640,height:360,maxBitrate:750_000,maxFramerate:20})]},
  game:{label:'Jogo',description:'1080p · até 60 fps · até 8 Mbps',width:1920,height:1080,fps:60,maxBitrate:8_000_000,contentHint:'motion',degradationPreference:'maintain-framerate',layers:[new VideoPreset({width:1280,height:720,maxBitrate:2_800_000,maxFramerate:30}),new VideoPreset({width:640,height:360,maxBitrate:800_000,maxFramerate:20})]},
};

const ICON_OPTIONS:IconOption[]=[{id:'user',label:'Pessoa',Icon:UserRound},{id:'users',label:'Equipe',Icon:Users},{id:'sparkles',label:'Brilho',Icon:Sparkles},{id:'gamepad',label:'Jogo',Icon:Gamepad2},{id:'code',label:'Código',Icon:Code2},{id:'rocket',label:'Foguete',Icon:Rocket},{id:'crown',label:'Coroa',Icon:Crown},{id:'shield',label:'Escudo',Icon:ShieldCheck},{id:'palette',label:'Arte',Icon:Palette},{id:'music',label:'Música',Icon:Music2},{id:'coffee',label:'Café',Icon:Coffee},{id:'cat',label:'Gato',Icon:Cat},{id:'star',label:'Estrela',Icon:Star}];
const ICON_COLORS=['#766cff','#4ed4c6','#f08b5d','#f05d77','#4d8df7','#b56cff','#e2b84b','#5bbf6a'];
const ICON_MAP=Object.fromEntries(ICON_OPTIONS.map(item=>[item.id,item.Icon])) as Record<string,LucideIcon>;

function AvatarBadge({icon,color,image,name,small=false,server=false,online=false}:{icon?:string;color?:string;image?:string|null;name:string;small?:boolean;server?:boolean;online?:boolean}){const Icon=ICON_MAP[icon||''];return <span className={`avatar visual-avatar ${small?'small':''} ${server?'server-icon':''} ${image?'has-image':''}`} style={{backgroundColor:color||'#766cff'}}>{image?<img src={image} alt=""/>:Icon?<Icon/>:initials(name)}{online&&<i/>}</span>;}
function AppearancePicker({icon,color,onIcon,onColor}:{icon:string;color:string;onIcon:(value:string)=>void;onColor:(value:string)=>void}){return <div className="appearance-picker"><div className="icon-options" role="group" aria-label="Escolha um ícone">{ICON_OPTIONS.map(item=><button type="button" key={item.id} className={icon===item.id?'selected':''} onClick={()=>onIcon(item.id)} title={item.label} aria-label={item.label}><item.Icon/></button>)}</div><div className="color-options" role="group" aria-label="Escolha uma cor">{ICON_COLORS.map(value=><button type="button" key={value} className={color===value?'selected':''} style={{backgroundColor:value}} onClick={()=>onColor(value)} title={value} aria-label={`Cor ${value}`}/>)}</div></div>;}

async function api<T>(path:string, options:RequestInit = {}):Promise<T> {
  const response = await fetch(path, { ...options, headers: { 'Content-Type':'application/json', ...(options.headers || {}) } });
  if (!response.ok) {
    const body = await response.json().catch(()=>({}));
    throw new Error(body.error || 'Não foi possível concluir a operação.');
  }
  return response.status === 204 ? (undefined as T) : response.json();
}
async function uploadImage<T>(path:string,file:File):Promise<T>{
  const response=await fetch(path,{method:'PUT',headers:{'Content-Type':file.type},body:file});
  if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'Não foi possível enviar a imagem.');}
  return response.json();
}
function validateImageFile(file:File):string{
  if(!['image/png','image/jpeg','image/webp'].includes(file.type))return 'Escolha uma imagem PNG, JPG ou WebP.';
  if(file.size>2*1024*1024)return 'A imagem deve ter no máximo 2 MB.';
  return '';
}

function initials(name:string){ return name.split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase(); }
function time(value:string){ return new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(value)); }
function dateLabel(value:string){ const d=new Date(value); const today=new Date(); return d.toDateString()===today.toDateString()?'Hoje':new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(d); }

function Auth({onAuthenticated}:{onAuthenticated:(user:User)=>void}){
  const [mode,setMode]=useState<'login'|'register'|'recover'>('login');
  const [form,setForm]=useState({email:'',password:'',username:'',displayName:'',recoveryCode:'',newPassword:''});
  const [error,setError]=useState('');
  const [loading,setLoading]=useState(false);
  const [showPassword,setShowPassword]=useState(false);
  const [newRecovery,setNewRecovery]=useState('');
  const [pendingUser,setPendingUser]=useState<User|null>(null);
  async function submit(e:React.FormEvent){
    e.preventDefault(); setError(''); setLoading(true);
    try{
      if(mode==='login'){
        const r=await api<{user:User}>('/api/auth/login',{method:'POST',body:JSON.stringify({email:form.email,password:form.password})}); onAuthenticated(r.user);
      }else if(mode==='register'){
        const r=await api<{user:User;recoveryCode:string}>('/api/auth/register',{method:'POST',body:JSON.stringify(form)}); setNewRecovery(r.recoveryCode); setPendingUser(r.user);
      }else{
        const r=await api<{recoveryCode:string}>('/api/auth/recover',{method:'POST',body:JSON.stringify({email:form.email,recoveryCode:form.recoveryCode,newPassword:form.newPassword})});
        setNewRecovery(r.recoveryCode); setMode('login'); setForm({...form,password:'',newPassword:'',recoveryCode:''});
      }
    }catch(err:any){setError(err.message);}finally{setLoading(false);}
  }
  return <div className="auth-shell">
    <div className="auth-orb orb-a"/><div className="auth-orb orb-b"/>
    <section className="auth-hero">
      <div className="brand large"><span className="brand-mark"><MonitorUp size={25}/></span><span>TelaHub</span></div>
      <h1>Converse.<br/><span>Mostre. Resolva.</span></h1>
      <p>Um espaço direto para equipes que precisam conversar por texto e compartilhar a tela sem distrações.</p>
      <div className="trust-row"><span><ShieldCheck size={17}/> Acesso protegido</span><span><Radio size={17}/> Tempo real</span></div>
    </section>
    <section className="auth-card">
      <div className="mobile-brand brand"><span className="brand-mark"><MonitorUp size={20}/></span><span>TelaHub</span></div>
      <p className="eyebrow">BEM-VINDO</p>
      <h2>{mode==='login'?'Entre no seu espaço':mode==='register'?'Crie sua conta':'Recupere o acesso'}</h2>
      <p className="muted">{mode==='login'?'Continue de onde sua equipe parou.':mode==='register'?'Seu primeiro espaço será criado automaticamente.':'Use o código entregue no seu cadastro.'}</p>
      <form onSubmit={submit}>
        {mode==='register'&&<><label>Nome de exibição<input required maxLength={40} value={form.displayName} onChange={e=>setForm({...form,displayName:e.target.value})} placeholder="Como devemos chamar você?"/></label><label>Nome de usuário<input required minLength={3} maxLength={24} value={form.username} onChange={e=>setForm({...form,username:e.target.value})} placeholder="usuario"/></label></>}
        <label>E-mail<input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="voce@empresa.com"/></label>
        {mode==='recover'&&<label>Código de recuperação<input required value={form.recoveryCode} onChange={e=>setForm({...form,recoveryCode:e.target.value.toUpperCase()})} placeholder="CÓDIGO SALVO"/></label>}
        <label>{mode==='recover'?'Nova senha':'Senha'}<span className="password-wrap"><input required minLength={8} type={showPassword?'text':'password'} value={mode==='recover'?form.newPassword:form.password} onChange={e=>mode==='recover'?setForm({...form,newPassword:e.target.value}):setForm({...form,password:e.target.value})} placeholder="Mínimo de 8 caracteres"/><button type="button" className="eye" onClick={()=>setShowPassword(!showPassword)}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></span></label>
        {error&&<div className="error-box">{error}</div>}
        <button className="primary wide" disabled={loading}>{loading?'Aguarde…':mode==='login'?'Entrar':mode==='register'?'Criar conta':'Redefinir senha'}</button>
      </form>
      <div className="auth-links">
        {mode!=='login'&&<button onClick={()=>setMode('login')}>Já tenho conta</button>}
        {mode!=='register'&&<button onClick={()=>setMode('register')}>Criar uma conta</button>}
        {mode!=='recover'&&<button onClick={()=>setMode('recover')}>Esqueci minha senha</button>}
      </div>
    </section>
    {newRecovery&&<div className="modal-backdrop"><div className="recovery-modal"><span className="modal-icon"><KeyRound/></span><h3>Guarde seu novo código</h3><p>Este código é a única forma de recuperar sua conta sem e-mail. Armazene-o em um local seguro.</p><code>{newRecovery}</code><button className="primary wide" onClick={()=>{setNewRecovery('');if(pendingUser)onAuthenticated(pendingUser);}}>Já salvei o código</button></div></div>}
  </div>
}

function ScreenTile({track,audioTrack,label,isLocal,meta,focused,onFocus}:{track:RemoteTrack|LocalTrack;audioTrack?:RemoteTrack;label:string;isLocal:boolean;meta?:CaptureInfo|null;focused:boolean;onFocus:()=>void}){
  const videoRef=useRef<HTMLVideoElement>(null); const audioRef=useRef<HTMLAudioElement>(null); const [volume,setVolume]=useState(1); const [muted,setMuted]=useState(false);
  useEffect(()=>{const el=videoRef.current;if(el)track.attach(el);return()=>{if(el)track.detach(el);};},[track]);
  useEffect(()=>{const el=audioRef.current;if(!el||!audioTrack)return;audioTrack.attach(el);el.volume=volume;el.muted=muted;el.play().catch(()=>{});return()=>{audioTrack.detach(el);};},[audioTrack]);
  useEffect(()=>{if(audioRef.current){audioRef.current.volume=volume;audioRef.current.muted=muted;}},[volume,muted]);
  return <div className={'screen-tile '+(focused?'focused':'')} onDoubleClick={onFocus}><video ref={videoRef} autoPlay playsInline/><span className="screen-label">{label}</span><button className="stream-focus" type="button" onClick={onFocus} title={focused?'Remover foco':'Focar transmissão'}>{focused?<PinOff/>:<Pin/>}<span>{focused?'Em foco':'Focar'}</span></button><span className={'stream-audio-source '+(audioTrack||meta?.hasAudio?'with-audio':'')}>{audioTrack||meta?.hasAudio?(meta?.mode==='system'?'Áudio do dispositivo':meta?.mode==='window'?'Áudio da fonte':'Com áudio'):'Sem áudio'}</span>{audioTrack&&<audio ref={audioRef} autoPlay playsInline/>}<div className="stream-volume">{isLocal?<span>Sua transmissão</span>:audioTrack?<><button type="button" onClick={()=>setMuted(value=>!value)} title={muted?'Ativar som':'Silenciar stream'}>{muted||volume===0?<VolumeX/>:<Volume2/>}</button><input type="range" min="0" max="100" step="1" value={Math.round(volume*100)} onChange={event=>{setVolume(Number(event.target.value)/100);setMuted(false);}} aria-label={`Volume da transmissão de ${label}`}/><output>{muted?'Mudo':`${Math.round(volume*100)}%`}</output></>:<span>Stream sem áudio</span>}</div></div>;
}

function AudioOutput({track}:{track:RemoteTrack}){
  const ref=useRef<HTMLAudioElement>(null);
  useEffect(()=>{const el=ref.current;if(el)track.attach(el);return()=>{if(el)track.detach(el);};},[track]);
  return <audio ref={ref} autoPlay playsInline/>;
}

function ScreenRoom({channel,user,socket}:{channel:Channel;user:User;socket:Socket}){
  const [room,setRoom]=useState<Room|null>(null); const [version,setVersion]=useState(0); const [status,setStatus]=useState('Conectando…'); const [sharing,setSharing]=useState(false); const [microphone,setMicrophone]=useState(false); const [focusedId,setFocusedId]=useState(''); const [audioMode,setAudioMode]=useState<AudioShareMode>('window'); const [quality,setQuality]=useState<StreamQuality>(()=>{const saved=localStorage.getItem('telahub-stream-quality');return saved&&saved in QUALITY_PROFILES?saved as StreamQuality:'balanced';}); const [liveBitrate,setLiveBitrate]=useState<number|null>(null); const [liveFps,setLiveFps]=useState<number|null>(null); const [qualityReason,setQualityReason]=useState<string>('none'); const [captureInfo,setCaptureInfo]=useState<CaptureInfo|null>(null); const [streamMeta,setStreamMeta]=useState<Record<string,CaptureInfo>>({}); const [error,setError]=useState(''); const qualityProfile=QUALITY_PROFILES[quality];
  useEffect(()=>{
    let active=true; const r=new Room({adaptiveStream:true,dynacast:true,disconnectOnPageLeave:true});
    const refresh=()=>active&&setVersion(v=>v+1);
    r.on(RoomEvent.TrackSubscribed,refresh)
      .on(RoomEvent.TrackUnsubscribed,refresh)
      .on(RoomEvent.ParticipantConnected,refresh)
      .on(RoomEvent.ParticipantDisconnected,refresh)
      .on(RoomEvent.LocalTrackPublished,refresh)
      .on(RoomEvent.LocalTrackUnpublished,(publication)=>{refresh();if(publication.source===Track.Source.ScreenShare){setSharing(false);setCaptureInfo(null);socket.emit('screen:status',{channelId:channel.id,active:false});}if(publication.source===Track.Source.Microphone)setMicrophone(false);})
      .on(RoomEvent.Reconnecting,()=>active&&setStatus('Reconectando…'))
      .on(RoomEvent.Reconnected,()=>active&&setStatus('Conectado'))
      .on(RoomEvent.Disconnected,()=>active&&setStatus('Desconectado'));
    api<{token:string;url:string}>('/api/livekit/token?channelId='+encodeURIComponent(channel.id)).then(async data=>{await r.connect(data.url,data.token,{autoSubscribe:true});if(active){setRoom(r);setStatus('Conectado');refresh();}}).catch((e)=>active&&(setError(e.message),setStatus('Falha na conexão')));
    return()=>{active=false;if(r.localParticipant.getTrackPublication(Track.Source.ScreenShare)?.track)socket.emit('screen:status',{channelId:channel.id,active:false});r.disconnect();};
  },[channel.id,socket]);
  useEffect(()=>{const onScreenStatus=(data:any)=>{if(data.active&&data.audioMode&&data.surface&&typeof data.hasAudio==='boolean')setStreamMeta(previous=>({...previous,[data.userId]:{mode:data.audioMode,surface:data.surface,hasAudio:data.hasAudio}}));else setStreamMeta(previous=>{const next={...previous};delete next[data.userId];return next;});};socket.on('screen:status',onScreenStatus);socket.emit('channel:join',channel.id);return()=>{socket.off('screen:status',onScreenStatus);};},[channel.id,socket]);
  useEffect(()=>{localStorage.setItem('telahub-stream-quality',quality);},[quality]);
  useEffect(()=>{if(!room||!sharing){setLiveBitrate(null);setLiveFps(null);setQualityReason('none');return;}let previousBytes=0;let previousTime=0;let stopped=false;const sample=async()=>{const localTrack:any=room.localParticipant.getTrackPublication(Track.Source.ScreenShare)?.track;const stats:RTCStatsReport|undefined=await localTrack?.sender?.getStats?.();if(!stats||stopped)return;let bytes=0;let timestamp=0;let fps=0;let reason='none';stats.forEach((entry:any)=>{if(entry.type==='outbound-rtp'&&(entry.kind==='video'||entry.mediaType==='video')&&!entry.isRemote){bytes+=entry.bytesSent||0;timestamp=Math.max(timestamp,entry.timestamp||0);fps=Math.max(fps,entry.framesPerSecond||0);if(entry.qualityLimitationReason&&entry.qualityLimitationReason!=='none')reason=entry.qualityLimitationReason;}});if(previousTime&&timestamp>previousTime&&bytes>=previousBytes)setLiveBitrate((bytes-previousBytes)*8/((timestamp-previousTime)/1000)/1_000_000);setLiveFps(fps||null);setQualityReason(reason);previousBytes=bytes;previousTime=timestamp;};sample();const timer=window.setInterval(sample,2000);return()=>{stopped=true;window.clearInterval(timer);};},[room,sharing]);
  async function toggleShare(){
    if(!room)return; setError('');
    try{
      if(sharing){await room.localParticipant.setScreenShareEnabled(false);setSharing(false);setCaptureInfo(null);socket.emit('screen:status',{channelId:channel.id,active:false});setVersion(v=>v+1);return;}
      if(!navigator.mediaDevices?.getDisplayMedia)throw new Error('Este navegador não oferece compartilhamento de tela.');
      const wantsAudio=audioMode!=='none';
      const displayOptions={
        video:{displaySurface:audioMode==='system'?'monitor':'window',width:{ideal:qualityProfile.width},height:{ideal:qualityProfile.height},frameRate:{ideal:qualityProfile.fps,max:qualityProfile.fps}},
        audio:wantsAudio?{restrictOwnAudio:true,suppressLocalAudioPlayback:false}:false,
        selfBrowserSurface:'exclude',surfaceSwitching:'include',monitorTypeSurfaces:'include',preferCurrentTab:false,
        systemAudio:audioMode==='system'?'include':'exclude',windowAudio:audioMode==='window'?'window':'exclude',
      } as unknown as DisplayMediaStreamOptions;
      const stream=await navigator.mediaDevices.getDisplayMedia(displayOptions);const videoTrack=stream.getVideoTracks()[0];const audioTrack=stream.getAudioTracks()[0];
      if(!videoTrack){stream.getTracks().forEach(track=>track.stop());throw new Error('Nenhuma imagem foi fornecida pelo navegador.');}
      videoTrack.contentHint=qualityProfile.contentHint;
      try{await room.localParticipant.publishTrack(videoTrack,{source:Track.Source.ScreenShare,stream:'screen-share',simulcast:true,screenShareEncoding:{maxBitrate:qualityProfile.maxBitrate,maxFramerate:qualityProfile.fps,priority:'high'},screenShareSimulcastLayers:qualityProfile.layers,degradationPreference:qualityProfile.degradationPreference});if(audioTrack)await room.localParticipant.publishTrack(audioTrack,{source:Track.Source.ScreenShareAudio,stream:'screen-share',forceStereo:true,audioPreset:AudioPresets.musicHighQualityStereo,dtx:false,red:true});}catch(publishError){stream.getTracks().forEach(track=>track.stop());await room.localParticipant.setScreenShareEnabled(false).catch(()=>{});throw publishError;}
      const settings=videoTrack.getSettings() as MediaTrackSettings&{displaySurface?:'browser'|'window'|'monitor'};const info:CaptureInfo={surface:settings.displaySurface||'unknown',hasAudio:Boolean(audioTrack),mode:audioMode};
      setCaptureInfo(info);setStreamMeta(previous=>({...previous,[user.id]:info}));setSharing(true);socket.emit('screen:status',{channelId:channel.id,active:true,audioMode:info.mode,surface:info.surface,hasAudio:info.hasAudio});setVersion(v=>v+1);
    }catch(e:any){setSharing(false);setCaptureInfo(null);if(e?.name!=='NotAllowedError')setError(e.message||'O navegador bloqueou o compartilhamento.');}
  }
  async function toggleMicrophone(){
    if(!room)return; setError('');
    try{const next=!microphone;await room.localParticipant.setMicrophoneEnabled(next);setMicrophone(next);setVersion(v=>v+1);}catch(e:any){setError(e.message||'Não foi possível acessar o microfone.');}
  }
  const tracks=useMemo(()=>{if(!room)return[] as {track:RemoteTrack|LocalTrack;audioTrack?:RemoteTrack;label:string;id:string;isLocal:boolean;meta?:CaptureInfo|null}[];const all=[room.localParticipant,...Array.from(room.remoteParticipants.values())];return all.flatMap(p=>{const pub=p.getTrackPublication(Track.Source.ScreenShare);const isLocal=p.identity===user.id;const audio=isLocal?undefined:p.getTrackPublication(Track.Source.ScreenShareAudio)?.track as RemoteTrack|undefined;return pub?.track?[{track:pub.track,audioTrack:audio,label:isLocal?'Sua tela':p.name||p.identity,id:p.identity,isLocal,meta:isLocal?captureInfo:streamMeta[p.identity]}]:[];});},[room,version,user.id,captureInfo,streamMeta]);
  const audioTracks=useMemo(()=>{if(!room)return[] as {track:RemoteTrack;id:string}[];return Array.from(room.remoteParticipants.values()).flatMap(p=>[p.getTrackPublication(Track.Source.Microphone)].filter(pub=>pub?.track).map(pub=>({track:pub!.track as RemoteTrack,id:`${p.identity}-${pub!.source}`})));},[room,version]);
  const focusedTrack=tracks.find(item=>item.id===focusedId); const remainingTracks=focusedTrack?tracks.filter(item=>item.id!==focusedId):tracks;
  useEffect(()=>{if(focusedId&&!tracks.some(item=>item.id===focusedId))setFocusedId('');},[focusedId,tracks]);
  const renderTile=(item:(typeof tracks)[number],focused=false)=><ScreenTile key={item.id} {...item} focused={focused} onFocus={()=>setFocusedId(current=>current===item.id?'':item.id)}/>;
  return <div className="screen-room">
    <div className="audio-outputs">{audioTracks.map(item=><AudioOutput key={item.id} track={item.track}/>)}</div>
    <div className="screen-toolbar"><div><span className={'status-dot '+(room&&status==='Conectado'?'online':'')}/><strong>{status}</strong><small>{tracks.length?`${tracks.length} tela${tracks.length>1?'s':''} ativa${tracks.length>1?'s':''} · áudio em tempo real`:'Nenhuma tela sendo compartilhada'}</small></div><div className="media-actions"><button className={microphone?'media-button active':'media-button'} disabled={!room} onClick={toggleMicrophone}>{microphone?<Mic size={18}/>:<MicOff size={18}/>}<span>{microphone?'Microfone ligado':'Ativar voz'}</span></button><button className={sharing?'danger':'primary'} disabled={!room} onClick={toggleShare}><MonitorUp size={18}/>{sharing?'Parar transmissão':'Iniciar transmissão'}</button></div></div>
    <div className="share-preferences quality-preferences"><div className="share-preferences-title"><Gauge size={16}/><div><strong>Qualidade e bitrate</strong><span>O WebRTC reduz automaticamente quando a conexão não sustenta o perfil.</span></div></div><div className="quality-mode-options" role="group" aria-label="Qualidade da transmissão">{(Object.entries(QUALITY_PROFILES) as [StreamQuality,QualityProfile][]).map(([id,profile])=><button type="button" key={id} className={quality===id?'active':''} disabled={sharing} onClick={()=>setQuality(id)}><strong>{profile.label}</strong><small>{profile.description}</small></button>)}</div><p className="capture-guidance">{sharing?`Perfil ${qualityProfile.label} · ${liveBitrate===null?'medindo bitrate…':`${liveBitrate.toFixed(2)} Mbps enviados agora`}${liveFps?` · ${Math.round(liveFps)} fps`:''}${qualityReason!=='none'?` · limitado por ${qualityReason==='bandwidth'?'rede':qualityReason==='cpu'?'CPU':qualityReason}`:' · adaptação livre'}`:`Selecione conforme sua conexão. Para jogos, o perfil Jogo prioriza fluidez; Equilibrado preserva nitidez.`}</p></div>
    <div className="share-preferences"><div className="share-preferences-title"><Volume2 size={16}/><div><strong>Áudio da transmissão</strong><span>Escolha o modo antes de abrir o seletor do navegador.</span></div></div><div className="audio-mode-options" role="group" aria-label="Modo de áudio"><button type="button" className={audioMode==='window'?'active':''} disabled={sharing} onClick={()=>setAudioMode('window')}><strong>Janela ou aba</strong><small>Solicita somente o áudio da fonte escolhida</small></button><button type="button" className={audioMode==='system'?'active':''} disabled={sharing} onClick={()=>setAudioMode('system')}><strong>Tela + dispositivo</strong><small>Pode transmitir o som de todos os aplicativos</small></button><button type="button" className={audioMode==='none'?'active':''} disabled={sharing} onClick={()=>setAudioMode('none')}><strong>Somente imagem</strong><small>Nenhum áudio será capturado</small></button></div><p className="capture-guidance">{captureInfo?`Captura ativa: ${captureInfo.surface==='browser'?'aba do navegador':captureInfo.surface==='window'?'janela':captureInfo.surface==='monitor'?'tela inteira':'fonte escolhida'} · ${captureInfo.hasAudio?'áudio recebido':'sem áudio fornecido pelo navegador'}`:audioMode==='window'?'Para isolar o jogo, escolha a janela do jogo. Se selecionar a tela inteira, o áudio poderá ficar indisponível para evitar transmitir outros aplicativos.':audioMode==='system'?'Use para tela inteira quando quiser incluir o áudio do dispositivo. Outros aplicativos também podem ser ouvidos.':'A transmissão enviará apenas a imagem.'}</p></div>
    {error&&<div className="error-box room-error">{error}</div>}
    <div className={'screen-layout '+(focusedTrack?'focused ':'')+(focusedTrack&&remainingTracks.length?'has-strip':'')}>{focusedTrack?<>{renderTile(focusedTrack,true)}{remainingTracks.length>0&&<div className="stream-strip">{remainingTracks.map(item=>renderTile(item))}</div>}</>:<div className={'screen-grid '+(tracks.length===1?'single':'')}>{tracks.length?tracks.map(item=>renderTile(item)):<div className="screen-empty"><span><MonitorUp size={42}/></span><h3>A sala está pronta</h3><p>Compartilhe uma aba, janela ou tela inteira com áudio e baixa latência.</p></div>}</div>}</div>
  </div>
}

function Chat({channel,user,socket}:{channel:Channel;user:User;socket:Socket}){
  const [messages,setMessages]=useState<Message[]>([]); const [content,setContent]=useState(''); const [typing,setTyping]=useState<string[]>([]); const endRef=useRef<HTMLDivElement>(null); const typingTimer=useRef<number|undefined>(undefined);
  useEffect(()=>{let active=true;setMessages([]);setTyping([]);api<{messages:Message[]}>('/api/channels/'+channel.id+'/messages').then(r=>{if(active)setMessages(r.messages);}).catch(()=>{if(active)setMessages([]);});socket.emit('channel:join',channel.id);const onMessage=(m:Message)=>{if(m.channel_id===channel.id)setMessages(prev=>prev.some(x=>x.id===m.id)?prev:[...prev,m]);};const onTyping=(d:any)=>{if(d.userId===user.id)return;setTyping(prev=>d.active?Array.from(new Set([...prev,d.displayName])):prev.filter(n=>n!==d.displayName));};const onProfile=(d:any)=>{const changed=d.user as User;setMessages(prev=>prev.map(message=>message.author_id===changed.id?{...message,display_name:changed.display_name,username:changed.username,avatar_icon:changed.avatar_icon,avatar_color:changed.avatar_color,avatar_image:changed.avatar_image}:message));};socket.on('message:new',onMessage);socket.on('typing',onTyping);socket.on('profile:updated',onProfile);return()=>{active=false;socket.off('message:new',onMessage);socket.off('typing',onTyping);socket.off('profile:updated',onProfile);};},[channel.id,socket,user.id]);
  useEffect(()=>{endRef.current?.scrollIntoView({behavior:'smooth'});},[messages.length]);
  function update(value:string){setContent(value);socket.emit('typing',{channelId:channel.id,active:true});window.clearTimeout(typingTimer.current);typingTimer.current=window.setTimeout(()=>socket.emit('typing',{channelId:channel.id,active:false}),1200);}
  function send(e:React.FormEvent){e.preventDefault();const text=content.trim();if(!text)return;socket.emit('message:send',{channelId:channel.id,content:text},(r:any)=>{if(!r?.ok)return;setContent('');socket.emit('typing',{channelId:channel.id,active:false});});}
  let previousDay='';
  return <div className="chat-area"><div className="messages">{messages.length===0&&<div className="channel-intro"><span><Hash size={30}/></span><h2>Bem-vindo a #{channel.name}</h2><p>Este é o começo deste canal. Envie a primeira mensagem.</p></div>}{messages.map(m=>{const day=dateLabel(m.created_at);const showDay=day!==previousDay;previousDay=day;return <React.Fragment key={m.id}>{showDay&&<div className="day-divider"><span>{day}</span></div>}<article className="message"><AvatarBadge icon={m.avatar_icon} color={m.avatar_color} image={m.avatar_image} name={m.display_name} small/><div><header><strong>{m.display_name}</strong><time>{time(m.created_at)}</time></header><p>{m.content}</p></div></article></React.Fragment>;})}<div ref={endRef}/></div><div className="typing-line">{typing.length?`${typing.join(', ')} está digitando…`:'\u00a0'}</div><form className="composer" onSubmit={send}><textarea rows={1} maxLength={4000} value={content} onChange={e=>update(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(e);}}} placeholder={`Mensagem em #${channel.name}`}/><button className="send" disabled={!content.trim()}><Send size={18}/></button></form></div>;
}

function ProfileSettings({user,onClose,onUpdated}:{user:User;onClose:()=>void;onUpdated:(user:User)=>void}){
  const [icon,setIcon]=useState(user.avatar_icon||'user'); const [color,setColor]=useState(user.avatar_color||'#766cff'); const [file,setFile]=useState<File|null>(null); const [removeImage,setRemoveImage]=useState(false); const [busy,setBusy]=useState(false); const [error,setError]=useState('');
  const preview=useMemo(()=>file?URL.createObjectURL(file):removeImage?null:user.avatar_image,[file,removeImage,user.avatar_image]);
  useEffect(()=>()=>{if(file&&preview)URL.revokeObjectURL(preview);},[file,preview]);
  function chooseFile(event:React.ChangeEvent<HTMLInputElement>){const selected=event.target.files?.[0];if(!selected)return;const problem=validateImageFile(selected);if(problem){setError(problem);event.target.value='';return;}setFile(selected);setRemoveImage(false);setError('');}
  async function save(){setBusy(true);setError('');try{let result=await api<{user:User}>('/api/users/me',{method:'PATCH',body:JSON.stringify({avatarIcon:icon,avatarColor:color})});if(file)result=await uploadImage<{user:User}>('/api/users/me/avatar',file);else if(removeImage&&user.avatar_image)result=await api<{user:User}>('/api/users/me/avatar',{method:'DELETE'});onUpdated(result.user);onClose();}catch(e:any){setError(e.message);}finally{setBusy(false);}}
  return <div className="modal-backdrop profile-backdrop" role="dialog" aria-modal="true" aria-label="Configurar ícone de perfil"><section className="profile-modal"><header><div><span className="eyebrow">SEU PERFIL</span><h2>Personalize seu ícone</h2><p>Envie uma imagem ou combine uma opção predefinida com sua cor preferida.</p></div><button className="icon-button" onClick={onClose} title="Fechar"><X/></button></header><div className="appearance-preview"><AvatarBadge icon={icon} color={color} image={preview} name={user.display_name}/><div><strong>{user.display_name}</strong><span>@{user.username}</span></div></div><div className="upload-controls"><label className="image-upload"><ImagePlus/><span><strong>Enviar imagem</strong><small>PNG, JPG ou WebP · até 2 MB</small></span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={chooseFile}/></label>{preview&&<button className="secondary remove-image" type="button" onClick={()=>{setFile(null);setRemoveImage(true);}}><ImageOff size={17}/>Usar ícone predefinido</button>}</div><AppearancePicker icon={icon} color={color} onIcon={setIcon} onColor={setColor}/>{error&&<div className="error-box">{error}</div>}<footer><button className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy} onClick={save}><Save size={17}/>{busy?'Salvando…':'Salvar perfil'}</button></footer></section></div>;
}

function SettingsPanel({community,members,user,onClose,onChanged,onDeleted}:{community:Community;members:Member[];user:User;onClose:()=>void;onChanged:()=>Promise<void>;onDeleted:()=>Promise<void>}){
  const [tab,setTab]=useState<'overview'|'channels'|'members'>('overview');
  const [name,setName]=useState(community.name); const [icon,setIcon]=useState(community.icon||'users'); const [color,setColor]=useState(community.icon_color||'#766cff'); const [imageFile,setImageFile]=useState<File|null>(null); const [removeImage,setRemoveImage]=useState(false); const [channelName,setChannelName]=useState(''); const [channelType,setChannelType]=useState<'text'|'screen'>('text'); const [confirmation,setConfirmation]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [notice,setNotice]=useState('');
  const isOwner=community.role==='owner';
  const imagePreview=useMemo(()=>imageFile?URL.createObjectURL(imageFile):removeImage?null:community.icon_image,[imageFile,removeImage,community.icon_image]);
  useEffect(()=>()=>{if(imageFile&&imagePreview)URL.revokeObjectURL(imagePreview);},[imageFile,imagePreview]);
  useEffect(()=>{setName(community.name);setIcon(community.icon||'users');setColor(community.icon_color||'#766cff');setImageFile(null);setRemoveImage(false);setConfirmation('');setError('');setNotice('');},[community.id,community.name,community.icon,community.icon_color,community.icon_image]);
  function chooseCommunityImage(event:React.ChangeEvent<HTMLInputElement>){const selected=event.target.files?.[0];if(!selected)return;const problem=validateImageFile(selected);if(problem){setError(problem);event.target.value='';return;}setImageFile(selected);setRemoveImage(false);setError('');}
  async function run(task:()=>Promise<void>,message:string){setBusy(true);setError('');setNotice('');try{await task();setNotice(message);await onChanged();}catch(e:any){setError(e.message);}finally{setBusy(false);}}
  async function saveIdentity(e:React.FormEvent){e.preventDefault();await run(async()=>{await api(`/api/communities/${community.id}`,{method:'PATCH',body:JSON.stringify({name,icon,iconColor:color})});if(imageFile)await uploadImage(`/api/communities/${community.id}/icon-image`,imageFile);else if(removeImage&&community.icon_image)await api(`/api/communities/${community.id}/icon-image`,{method:'DELETE'});setImageFile(null);setRemoveImage(false);},'Identidade da comunidade atualizada.');}
  async function rotateInvite(){if(!confirm('O convite atual deixará de funcionar. Gerar um novo código?'))return;await run(async()=>{await api(`/api/communities/${community.id}/invite/rotate`,{method:'POST'});},'Novo convite gerado.');}
  async function createChannel(e:React.FormEvent){e.preventDefault();await run(async()=>{await api(`/api/communities/${community.id}/channels`,{method:'POST',body:JSON.stringify({name:channelName,type:channelType})});setChannelName('');},'Canal criado.');}
  async function renameChannel(channel:Channel){const next=prompt('Novo nome do canal:',channel.name)?.trim();if(!next||next===channel.name)return;await run(async()=>{await api(`/api/channels/${channel.id}`,{method:'PATCH',body:JSON.stringify({name:next})});},'Canal renomeado.');}
  async function deleteChannel(channel:Channel){if(!confirm(`Excluir #${channel.name}? As mensagens deste canal serão apagadas.`))return;await run(async()=>{await api(`/api/channels/${channel.id}`,{method:'DELETE'});},'Canal excluído.');}
  async function moveChannel(index:number,direction:-1|1){const next=[...community.channels];const target=index+direction;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];await run(async()=>{await api(`/api/communities/${community.id}/channels/order`,{method:'PATCH',body:JSON.stringify({channelIds:next.map(channel=>channel.id)})});},'Ordem atualizada.');}
  async function changeRole(member:Member,role:'admin'|'member'){await run(async()=>{await api(`/api/communities/${community.id}/members/${member.id}`,{method:'PATCH',body:JSON.stringify({role})});},'Função atualizada.');}
  async function removeMember(member:Member){if(!confirm(`Remover ${member.display_name} da comunidade?`))return;await run(async()=>{await api(`/api/communities/${community.id}/members/${member.id}`,{method:'DELETE'});},'Membro removido.');}
  async function deleteCommunity(){if(confirmation!==community.name)return;setBusy(true);setError('');try{await api(`/api/communities/${community.id}`,{method:'DELETE',body:JSON.stringify({confirmation})});await onDeleted();}catch(e:any){setError(e.message);setBusy(false);}}
  return <section className="settings-shell">
    <aside className="settings-nav"><div className="settings-community-title"><AvatarBadge icon={community.icon} color={community.icon_color} image={community.icon_image} name={community.name} small server/><div><span className="eyebrow">CONFIGURAÇÕES</span><h2>{community.name}</h2></div></div><nav><button className={tab==='overview'?'active':''} onClick={()=>setTab('overview')}><Settings size={17}/>Visão geral</button><button className={tab==='channels'?'active':''} onClick={()=>setTab('channels')}><Hash size={17}/>Canais</button><button className={tab==='members'?'active':''} onClick={()=>setTab('members')}><UserCog size={17}/>Membros</button></nav></aside>
    <div className="settings-page"><div className="settings-top"><div><span className="eyebrow">PAINEL ADMINISTRATIVO</span><h1>{tab==='overview'?'Visão geral':tab==='channels'?'Canais':'Membros'}</h1></div><button className="icon-button close-settings" onClick={onClose} title="Fechar configurações"><X/></button></div>
      {(error||notice)&&<div className={error?'error-box':'success-box'}>{error||notice}</div>}
      {tab==='overview'&&<div className="settings-content"><article className="settings-card identity-card"><header><div><h3>Identidade da comunidade</h3><p>Envie uma imagem ou escolha um ícone e uma cor para todos os membros.</p></div><AvatarBadge icon={icon} color={color} image={imagePreview} name={name||community.name} server/></header><div className="upload-controls"><label className="image-upload"><ImagePlus/><span><strong>Enviar imagem do servidor</strong><small>PNG, JPG ou WebP · até 2 MB</small></span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={chooseCommunityImage}/></label>{imagePreview&&<button className="secondary remove-image" type="button" onClick={()=>{setImageFile(null);setRemoveImage(true);}}><ImageOff size={17}/>Usar ícone predefinido</button>}</div><AppearancePicker icon={icon} color={color} onIcon={setIcon} onColor={setColor}/><form className="settings-form" onSubmit={saveIdentity}><label>Nome da comunidade<input required minLength={2} maxLength={50} value={name} onChange={e=>setName(e.target.value)}/></label><button className="primary" disabled={busy||(name.trim()===community.name&&icon===community.icon&&color===community.icon_color&&!imageFile&&!removeImage)}><Save size={17}/>Salvar identidade</button></form></article><article className="settings-card"><header><div><h3>Convite</h3><p>Compartilhe o código com as pessoas que podem entrar.</p></div></header><div className="invite-control"><code>{community.invite_code}</code><button className="secondary" onClick={()=>navigator.clipboard.writeText(community.invite_code)}><Copy size={16}/>Copiar</button><button className="secondary" disabled={busy} onClick={rotateInvite}><RotateCw size={16}/>Gerar novo</button></div></article>{isOwner&&<article className="settings-card danger-zone"><header><div><h3>Excluir comunidade</h3><p>Esta ação remove canais, mensagens e associações permanentemente.</p></div></header><label>Digite <strong>{community.name}</strong> para confirmar<input value={confirmation} onChange={e=>setConfirmation(e.target.value)}/></label><button className="danger" disabled={busy||confirmation!==community.name} onClick={deleteCommunity}><Trash2 size={17}/>Excluir comunidade</button></article>}</div>}
      {tab==='channels'&&<div className="settings-content"><article className="settings-card"><header><div><h3>Criar canal</h3><p>Adicione conversas de texto ou salas de tela e áudio.</p></div></header><form className="channel-create-form" onSubmit={createChannel}><input required minLength={2} maxLength={40} placeholder="nome-do-canal" value={channelName} onChange={e=>setChannelName(e.target.value)}/><select value={channelType} onChange={e=>setChannelType(e.target.value as 'text'|'screen')}><option value="text">Texto</option><option value="screen">Tela e áudio</option></select><button className="primary" disabled={busy}><Plus size={17}/>Criar canal</button></form></article><article className="settings-card"><header><div><h3>Ordem e gerenciamento</h3><p>Organize, renomeie ou exclua os canais existentes.</p></div></header><div className="managed-list">{community.channels.map((channel,index)=><div className="managed-row" key={channel.id}><span className="channel-type-icon">{channel.type==='text'?<Hash/>:<MonitorUp/>}</span><div><strong>{channel.name}</strong><small>{channel.type==='text'?'Canal de texto':'Tela e áudio'}</small></div><div className="row-actions"><button className="icon-button" disabled={busy||index===0} onClick={()=>moveChannel(index,-1)} title="Mover para cima"><ChevronUp/></button><button className="icon-button" disabled={busy||index===community.channels.length-1} onClick={()=>moveChannel(index,1)} title="Mover para baixo"><ChevronDown/></button><button className="icon-button" disabled={busy} onClick={()=>renameChannel(channel)} title="Renomear"><Pencil/></button><button className="icon-button danger-icon" disabled={busy||community.channels.length<=1} onClick={()=>deleteChannel(channel)} title="Excluir"><Trash2/></button></div></div>)}</div></article></div>}
      {tab==='members'&&<div className="settings-content"><article className="settings-card"><header><div><h3>Membros da comunidade</h3><p>Gerencie funções e remova acessos quando necessário.</p></div><span className="count-badge">{members.length}</span></header><div className="managed-list member-admin-list">{members.map(member=><div className="managed-row" key={member.id}><AvatarBadge icon={member.avatar_icon} color={member.avatar_color} image={member.avatar_image} name={member.display_name} small online={member.online}/><div><strong>{member.display_name}{member.id===user.id&&<em>Você</em>}</strong><small>@{member.username}</small></div><div className="member-role-actions">{isOwner&&member.role!=='owner'?<select value={member.role} disabled={busy} onChange={e=>changeRole(member,e.target.value as 'admin'|'member')}><option value="member">Membro</option><option value="admin">Administrador</option></select>:<span className={`role-pill ${member.role}`}>{member.role==='owner'?'Proprietário':member.role==='admin'?'Administrador':'Membro'}</span>}{member.role!=='owner'&&member.id!==user.id&&(isOwner||community.role==='admin'&&member.role==='member')&&<button className="icon-button danger-icon" disabled={busy} onClick={()=>removeMember(member)} title="Remover membro"><Trash2/></button>}</div></div>)}</div></article></div>}
    </div>
  </section>;
}

function App(){
  const [user,setUser]=useState<User|null>(null); const [loading,setLoading]=useState(true); const [communities,setCommunities]=useState<Community[]>([]); const [activeCommunityId,setActiveCommunityId]=useState(''); const [activeChannelId,setActiveChannelId]=useState(''); const [members,setMembers]=useState<Member[]>([]); const [mobilePanel,setMobilePanel]=useState(false); const [settingsOpen,setSettingsOpen]=useState(false); const [profileOpen,setProfileOpen]=useState(false); const activeCommunityRef=useRef('');
  const socket=useMemo(()=>user?io({withCredentials:true,autoConnect:true}):null,[user?.id]);
  async function loadCommunities(preferredCommunity?:string){const r=await api<{communities:Community[]}>('/api/communities');setCommunities(r.communities);const nextCommunity=r.communities.find(c=>c.id===(preferredCommunity||activeCommunityId))||r.communities[0];if(nextCommunity){setActiveCommunityId(nextCommunity.id);const nextChannel=nextCommunity.channels.find(c=>c.id===activeChannelId)||nextCommunity.channels[0];setActiveChannelId(nextChannel?.id||'');}else{setActiveCommunityId('');setActiveChannelId('');setMembers([]);}}
  async function loadMembers(communityId:string){const r=await api<{members:Member[]}>(`/api/communities/${communityId}/members`);setMembers(r.members);}
  useEffect(()=>{api<{user:User}>('/api/auth/me').then(r=>setUser(r.user)).catch(()=>setUser(null)).finally(()=>setLoading(false));},[]);
  useEffect(()=>{if(user)loadCommunities();},[user]);
  useEffect(()=>{activeCommunityRef.current=activeCommunityId;if(!activeCommunityId)return;loadMembers(activeCommunityId).catch(()=>{});},[activeCommunityId]);
  useEffect(()=>{if(!socket)return;const presence=(d:any)=>setMembers(prev=>prev.map(m=>m.id===d.userId?{...m,online:d.online}:m));const changed=(d:any)=>{const activeId=activeCommunityRef.current;if(d.communityId===activeId){loadCommunities(activeId).catch(()=>{});loadMembers(activeId).catch(()=>{});}};const profile=(d:any)=>{const changedUser=d.user as User;setMembers(prev=>prev.map(member=>member.id===changedUser.id?{...member,...changedUser}:member));if(changedUser.id===user?.id)setUser(changedUser);};socket.on('presence:update',presence);socket.on('community:updated',changed);socket.on('profile:updated',profile);return()=>{socket.off('presence:update',presence);socket.off('community:updated',changed);socket.off('profile:updated',profile);socket.disconnect();};},[socket,user?.id]);
  const community=communities.find(c=>c.id===activeCommunityId); const channel=community?.channels.find(c=>c.id===activeChannelId);
  async function createCommunity(){const name=prompt('Nome da nova comunidade:')?.trim();if(!name)return;const r=await api<{id:string}>('/api/communities',{method:'POST',body:JSON.stringify({name})});await loadCommunities(r.id);}
  async function joinCommunity(){const code=prompt('Código de convite:')?.trim();if(!code)return;try{const r=await api<{id:string}>('/api/communities/join',{method:'POST',body:JSON.stringify({inviteCode:code})});await loadCommunities(r.id);}catch(e:any){alert(e.message);}}
  async function createChannel(){if(!community)return;const name=prompt('Nome do canal:')?.trim();if(!name)return;const type=confirm('OK para canal de compartilhamento de tela.\nCancelar para canal de texto.')?'screen':'text';try{await api(`/api/communities/${community.id}/channels`,{method:'POST',body:JSON.stringify({name,type})});await loadCommunities(community.id);}catch(e:any){alert(e.message);}}
  async function logout(){await api('/api/auth/logout',{method:'POST'});setUser(null);setCommunities([]);setSettingsOpen(false);setProfileOpen(false);}
  async function refreshSettings(){if(!community)return;await Promise.all([loadCommunities(community.id),loadMembers(community.id)]);}
  async function afterCommunityDeleted(){setSettingsOpen(false);await loadCommunities();}
  if(loading)return <div className="splash"><span className="brand-mark"><MonitorUp/></span><p>Preparando seu espaço…</p></div>;
  if(!user)return <Auth onAuthenticated={setUser}/>;
  return <div className="app-shell">
    <aside className="server-rail"><div className="rail-logo"><MonitorUp size={22}/></div><div className="rail-line"/>{communities.map(c=><button key={c.id} onClick={()=>{setActiveCommunityId(c.id);setActiveChannelId(c.channels[0]?.id||'');setSettingsOpen(false);}} className={'server-bubble '+(c.id===activeCommunityId?'active':'')} title={c.name}><AvatarBadge icon={c.icon} color={c.icon_color} image={c.icon_image} name={c.name} server/></button>)}<button className="server-bubble add" onClick={createCommunity} title="Criar comunidade"><Plus size={20}/></button><button className="server-bubble join" onClick={joinCommunity} title="Entrar por convite">+</button></aside>
    <aside className={'channel-panel '+(mobilePanel?'open':'')}><header><div><span>COMUNIDADE</span><strong>{community?.name||'TelaHub'}</strong></div>{community&&<div className="community-header-actions"><button title="Copiar convite" onClick={()=>navigator.clipboard.writeText(community.invite_code)}><Copy size={16}/></button>{['owner','admin'].includes(community.role)&&<button title="Configurações da comunidade" onClick={()=>{setSettingsOpen(true);setMobilePanel(false);}}><Settings size={17}/></button>}</div>}</header><div className="channel-list"><div className="channel-section"><span>CANAIS DE TEXTO</span>{community&&['owner','admin'].includes(community.role)&&<button onClick={createChannel}><Plus size={15}/></button>}</div>{community?.channels.filter(c=>c.type==='text').map(c=><button key={c.id} className={c.id===activeChannelId?'active':''} onClick={()=>{setActiveChannelId(c.id);setMobilePanel(false);}}><Hash size={18}/><span>{c.name}</span></button>)}<div className="channel-section top-gap"><span>SALAS DE TELA</span></div>{community?.channels.filter(c=>c.type==='screen').map(c=><button key={c.id} className={c.id===activeChannelId?'active':''} onClick={()=>{setActiveChannelId(c.id);setMobilePanel(false);}}><MonitorUp size={18}/><span>{c.name}</span></button>)}</div><footer><button className="profile-trigger" onClick={()=>setProfileOpen(true)} title="Personalizar ícone do perfil"><AvatarBadge icon={user.avatar_icon} color={user.avatar_color} image={user.avatar_image} name={user.display_name}/><span><strong>{user.display_name}</strong><small>@{user.username}</small></span><Pencil size={14}/></button><button onClick={logout} title="Sair"><LogOut size={18}/></button></footer></aside>
    <main>{settingsOpen&&community?<SettingsPanel community={community} members={members} user={user} onClose={()=>setSettingsOpen(false)} onChanged={refreshSettings} onDeleted={afterCommunityDeleted}/>:<><header className="topbar"><button className="mobile-menu" onClick={()=>setMobilePanel(!mobilePanel)}>☰</button>{channel?.type==='text'?<Hash size={20}/>:<MonitorUp size={20}/>}<strong>{channel?.name||'selecione-um-canal'}</strong><span>{channel?.type==='text'?'Conversa em tempo real':'Sala de compartilhamento de tela'}</span><div className="connection"><Wifi size={16}/> Online</div></header>{channel&&socket?(channel.type==='text'?<Chat channel={channel} user={user} socket={socket}/>:<ScreenRoom channel={channel} user={user} socket={socket}/>):<div className="empty-main">Selecione um canal.</div>}</>}</main>
    <aside className="members-panel"><header><Users size={17}/><span>MEMBROS — {members.length}</span></header><div className="members"><p className="member-group">ONLINE</p>{members.filter(m=>m.online||m.id===user.id).map(m=><div className="member" key={m.id}><AvatarBadge icon={m.avatar_icon} color={m.avatar_color} image={m.avatar_image} name={m.display_name} small online/><div><strong>{m.display_name}</strong><span>{m.role==='owner'?'Proprietário':m.role==='admin'?'Administrador':'Membro'}</span></div></div>)}<p className="member-group">OFFLINE</p>{members.filter(m=>!m.online&&m.id!==user.id).map(m=><div className="member offline" key={m.id}><AvatarBadge icon={m.avatar_icon} color={m.avatar_color} image={m.avatar_image} name={m.display_name} small/><div><strong>{m.display_name}</strong><span>Visto recentemente</span></div></div>)}</div></aside>
  {profileOpen&&<ProfileSettings user={user} onClose={()=>setProfileOpen(false)} onUpdated={setUser}/>}</div>;
}

class AppErrorBoundary extends React.Component<{children:React.ReactNode},{error:string}> {
  state={error:''};
  static getDerivedStateFromError(){return{error:'A interface encontrou uma falha inesperada.'};}
  componentDidCatch(error:Error,info:React.ErrorInfo){console.error('TelaHub interface error',error,info);}
  render(){return this.state.error?<div className="fatal-error"><span className="brand-mark"><MonitorUp/></span><h1>Não foi possível abrir este espaço</h1><p>{this.state.error}</p><button className="primary" onClick={()=>location.reload()}>Tentar novamente</button></div>:this.props.children;}
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><AppErrorBoundary><App/></AppErrorBoundary></React.StrictMode>);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
